mapper.update:
update user_wallet
balance = #{balance}, frozen = #{frozen}, total_earned = #{totalEarned}, total_withdrawn = #{totalWithdrawn}, update_time = now()
where uid = #{uid}

mapper.select:
select id, uid, amount, status, remark, wx_transfer_no, out_batch_no, out_detail_no, wx_detail_no, fail_type, user_message, create_time
from wallet_withdraw
where id = #{id}

mapper.update:
update wallet_withdraw
status = #{status}, remark = #{remark}, wx_transfer_no = #{wxTransferNo}, out_batch_no = #{outBatchNo}, out_detail_no = #{outDetailNo}, wx_detail_no = #{wxDetailNo}, fail_type = #{failType}, user_message = #{userMessage}, update_time = now()
where id = #{id}

mapper.select:
select id, uid, biz_type, biz_id, direction, amount, balance_after, remark, create_time
from wallet_transaction
where biz_type = #{bizType}
  and biz_id = #{bizId}
limit 1
